namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeSubmitModel
{
    [Required(ErrorMessage = "Title is required.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = "";

    public string OtherCategory { get; set; } = "";

    [Required(ErrorMessage = "At least one ingredient is required.")]
    [MinLength(1, ErrorMessage = "At least one ingredient is required.")]
    public string IngredientsText { get; set; } = "";

    [Required(ErrorMessage = "At least one step is required.")]
    [MinLength(1, ErrorMessage = "At least one step is required.")]
    public string StepsText { get; set; } = "";

    public string Description { get; set; } = "";
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Lock _lock = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new Recipe
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a weekend morning.",
                Ingredients = new List<string> { "1½ cups all-purpose flour", "3½ tsp baking powder", "1 egg", "1¼ cups milk", "3 tbsp melted butter" },
                Steps = new List<string> { "Whisk flour, baking powder, and a pinch of salt together.", "Beat egg, milk, and melted butter, then combine with dry ingredients.", "Pour batter onto a hot greased griddle and cook until bubbles form, then flip.", "Serve warm with maple syrup and fresh berries." },
                AverageRating = 4.5, RatingCount = 12
            },
            new Recipe
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple and delicious avocado toast with a kick of lemon.",
                Ingredients = new List<string> { "2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Red pepper flakes", "Salt and pepper" },
                Steps = new List<string> { "Toast the sourdough slices until golden brown.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread the mashed avocado on the toast.", "Sprinkle with red pepper flakes and serve." },
                AverageRating = 4.2, RatingCount = 8
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A hearty Italian classic with rich meat sauce.",
                Ingredients = new List<string> { "400g spaghetti", "500g ground beef", "1 can crushed tomatoes", "1 onion, diced", "3 cloves garlic, minced" },
                Steps = new List<string> { "Cook spaghetti according to package directions.", "Brown the beef with onion and garlic in a large pan.", "Add crushed tomatoes and simmer for 20 minutes.", "Serve the sauce over the spaghetti with grated Parmesan." },
                AverageRating = 4.7, RatingCount = 20
            },
            new Recipe
            {
                Id = 4, Title = "Grilled Chicken Tacos", Category = "Dinner",
                Description = "Flavorful grilled chicken tacos with fresh toppings.",
                Ingredients = new List<string> { "2 chicken breasts", "8 small tortillas", "1 cup shredded lettuce", "½ cup salsa", "1 lime" },
                Steps = new List<string> { "Season chicken with cumin, chili powder, salt, and grill until cooked through.", "Slice the chicken into strips.", "Warm tortillas and fill with chicken, lettuce, and salsa.", "Squeeze lime over the tacos and serve." },
                AverageRating = 4.4, RatingCount = 15
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Decadent individual cakes with a molten chocolate center.",
                Ingredients = new List<string> { "200g dark chocolate", "100g butter", "2 eggs", "2 egg yolks", "¼ cup sugar", "2 tbsp flour" },
                Steps = new List<string> { "Melt chocolate and butter together, then let cool slightly.", "Whisk eggs, yolks, and sugar until thick, then fold in the chocolate mixture and flour.", "Pour into greased ramekins and bake at 220°C for 12 minutes.", "Invert onto plates and serve immediately." },
                AverageRating = 4.9, RatingCount = 25
            },
            new Recipe
            {
                Id = 6, Title = "Strawberry Cheesecake", Category = "Desserts",
                Description = "Creamy no-bake cheesecake topped with fresh strawberries.",
                Ingredients = new List<string> { "200g digestive biscuits", "100g melted butter", "500g cream cheese", "1 cup powdered sugar", "Fresh strawberries" },
                Steps = new List<string> { "Crush biscuits and mix with melted butter, press into a springform pan.", "Beat cream cheese and sugar until smooth, spread over the base.", "Refrigerate for at least 4 hours until set.", "Top with sliced strawberries before serving." },
                AverageRating = 4.6, RatingCount = 18
            }
        };
        _nextId = 7;
    }

    public List<Recipe> GetAllRecipes()
    {
        lock (_lock)
        {
            return _recipes.ToList();
        }
    }

    public List<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public List<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().ToList();
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _nextId++;
            _recipes.Add(recipe);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null)
            {
                var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
                recipe.RatingCount++;
                recipe.AverageRating = totalStars / recipe.RatingCount;
            }
        }
    }
}

