arguments.file_text:
@page "/recipes"
@page "/recipes/{Category}"
@inject RecipeService RecipeService

<PageTitle>@(string.IsNullOrEmpty(Category) ? "All Recipes" : Category + " Recipes") - RecipeShare</PageTitle>

<h1>@(string.IsNullOrEmpty(Category) ? "All Recipes" : Category + " Recipes")</h1>

@if (!string.IsNullOrEmpty(Category))
{
    <a href="recipes" class="btn btn-outline-secondary btn-sm mb-3">← All Categories</a>
}

<div class="row">
    @foreach (var recipe in recipes)
    {
        <div class="col-md-6 col-lg-4 mb-4">
            <div class="card recipe-card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <span class="badge bg-secondary mb-2">@recipe.Category</span>
                    <p class="card-text">@recipe.Description</p>
                    <div class="mb-2">
                        @for (int i = 1; i <= 5; i++)
                        {
                            @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                        }
                        <small class="text-muted">(@recipe.AverageRating.ToString("F1")) · @recipe.RatingCount ratings</small>
                    </div>
                    <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@if (!recipes.Any())
{
    <p class="text-muted">No recipes found in this category.</p>
}

@code {
    [Parameter] public string? Category { get; set; }

    private List<Recipe> recipes = new();

    protected override void OnInitialized()
    {
        recipes = string.IsNullOrEmpty(Category)
            ? RecipeService.GetAllRecipes()
            : RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeService RecipeService

@if (recipe is not null)
{
    <PageTitle>@recipe.Title - RecipeShare</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">Recipes</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>
    <p class="lead">@recipe.Description</p>

    <div class="row">
