    {
        var starValue = i;
        <span class="star @(IsStarFilled(starValue) ? "filled" : "")"
              @onmouseover="() => hoverValue = starValue"
              @onmouseout="() => hoverValue = 0"
              @onclick="() => SubmitRating(starValue)">
            @(IsStarFilled(starValue) ? "★" : "☆")
        </span>
    }
    <span class="ms-2 text-muted">
        @displayRating.ToString("F1") avg · @displayCount rating(s)
