@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoverValue;
    private bool hasRated;
    private double displayRating;
    private int displayCount;

    protected override void OnParametersSet()
    {
        if (!hasRated)
        {
            displayRating = CurrentRating;
            displayCount = RatingCount;
        }
    }

    private bool IsStarFilled(int star)
    {
        if (hoverValue > 0)
            return star <= hoverValue;
        return star <= (int)Math.Round(displayRating);
    }

    private void SubmitRating(int stars)
    {
        if (hasRated) return;

        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            displayRating = recipe.AverageRating;
            displayCount = recipe.RatingCount;
        }
        hasRated = true;
    }
}

