 @page "/submit"
 @rendermode InteractiveServer
 @inject RecipeService RecipeService

 <PageTitle>Submit a Recipe - RecipeShare</PageTitle>

 <h1>Submit a Recipe</h1>

 @if (submitted)
 {
     <div class="alert alert-success">
         <h4>Recipe submitted successfully!</h4>
         <p>Your recipe "<strong>@model.Title</strong>" has been added.</p>
         <a href="recipes" class="btn btn-primary">Browse Recipes</a>
     </div>
 }
 else
 {
     <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
         <DataAnnotationsValidator />
         <ValidationSummary class="text-danger" />

         <div class="mb-3">
             <label for="title" class="form-label">Title</label>
             <InputText id="title" class="form-control" @bind-Value="model.Title" />
             <ValidationMessage For="() => model.Title" />
         </div>

         <div class="mb-3">
             <label for="description" class="form-label">Description</label>
             <InputTextArea id="description" class="form-control" @bind-Value="model.Description" rows="2" />
         </div>

         <div class="mb-3">
             <label for="category" class="form-label">Category</label>
             <InputSelect id="category" class="form-select" @bind-Value="model.Category">
                 <option value="">-- Select a category --</option>
                 @foreach (var cat in categories)
                 {
                     <option value="@cat">@cat</option>
                 }
                 <option value="Other">Other</option>
             </InputSelect>
             <ValidationMessage For="() => model.Category" />
         </div>

         @if (model.Category == "Other")
         {
             <div class="mb-3">
                 <label for="otherCategory" class="form-label">New Category Name</label>
                 <InputText id="otherCategory" class="form-control" @bind-Value="model.OtherCategory" />
             </div>
         }

         <div class="mb-3">
             <label for="ingredients" class="form-label">Ingredients (one per line)</label>
             <InputTextArea id="ingredients" class="form-control" @bind-Value="model.IngredientsText" rows="5" />
             <ValidationMessage For="() => model.IngredientsText" />
         </div>

         <div class="mb-3">
             <label for="steps" class="form-label">Steps (one per line)</label>
             <InputTextArea id="steps" class="form-control" @bind-Value="model.StepsText" rows="5" />
             <ValidationMessage For="() => model.StepsText" />
         </div>

         <button type="submit" class="btn btn-success">Submit Recipe</button>
     </EditForm>
 }

 @code {
     private RecipeSubmitModel model = new();
     private List<string> categories = new();
     private bool submitted;

     protected override void OnInitialized()
     {
         categories = RecipeService.GetCategories();
     }

     private void HandleSubmit()
     {
         var ingredients = model.IngredientsText
             .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
             .ToList();

         var steps = model.StepsText
             .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
             .ToList();

         if (ingredients.Count == 0 || steps.Count == 0)
             return;

         var category = model.Category == "Other" && !string.IsNullOrWhiteSpace(model.OtherCategory)
             ? model.OtherCategory.Trim()
             : model.Category;

         var recipe = new Recipe
         {
             Title = model.Title.Trim(),
             Category = category,
             Description = model.Description.Trim(),
             Ingredients = ingredients,
             Steps = steps
         };

         RecipeService.AddRecipe(recipe);
         submitted = true;
     }
 }

